/* submit */ pthread_mutex_lock(&q.m); q.push(t); pthread_cond_signal(&q.ready); pthread_mutex_unlock(&q.m);
/* worker */ for (;;) {
    pthread_mutex_lock(&q.m);
    while (!q.len && !q.stop) pthread_cond_wait(&q.ready, &q.m);
    if (!q.len && q.stop) { pthread_mutex_unlock(&q.m); break; }
    t = q.pop(); pthread_mutex_unlock(&q.m);
    t->fn(t->arg);                       /* must not block on this pool */
}
q.stop = 1; pthread_cond_broadcast(&q.ready);
